<x-app-layout>
    <div class="d-flex flex-wrap justify-content-between align-items-end gap-3 mb-4"><div><span class="badge rounded-pill badge-soft px-3 py-2 mb-2"><i class="bi bi-camera me-1"></i> Correção assistida</span><h1 class="h3 brand-font fw-bold mb-1">Corrigir prova</h1><p class="text-muted-custom mb-0">Leia o QRCode, confira o aluno e registre as respostas.</p></div><a href="{{ route('dashboard') }}" class="btn btn-light"><i class="bi bi-arrow-left me-2"></i>Voltar ao painel</a></div>
    <div id="scannerAlert"></div>
    <div class="row g-4"><div class="col-xl-5"><div class="card-soft p-4 h-100"><div class="d-flex justify-content-between align-items-center mb-3"><div><h2 class="h5 brand-font fw-bold mb-1">1. Leia o QRCode</h2><p class="small text-muted-custom mb-0">Use a câmera do computador ou celular.</p></div><span class="badge bg-light text-dark"><i class="bi bi-shield-check text-success me-1"></i>Seguro</span></div><div class="scanner-box p-3"><div id="reader" style="width:100%"></div></div><div class="d-flex gap-2 mt-3"><button id="startScanner" class="btn btn-primary flex-grow-1"><i class="bi bi-camera-fill me-2"></i>Ativar câmera</button><button id="stopScanner" class="btn btn-light" disabled><i class="bi bi-stop-circle"></i></button></div><div class="small text-muted-custom mt-3"><i class="bi bi-info-circle me-1"></i>O QRCode contém apenas a identificação do aluno e da prova.</div></div></div><div class="col-xl-7"><div class="card-soft p-4 h-100"><div class="d-flex justify-content-between align-items-center mb-3"><div><h2 class="h5 brand-font fw-bold mb-1">2. Registre as respostas</h2><p class="small text-muted-custom mb-0">Selecione a alternativa marcada pelo aluno.</p></div><span class="badge bg-light text-dark"><i class="bi bi-pencil-square me-1"></i>Formulário</span></div><livewire:correcao-form /></div></div></div>
    @push('scripts')<script src="https://unpkg.com/html5-qrcode@2.3.8/html5-qrcode.min.js"></script><script>let scanner=null,active=false;const alertBox=(message,type='danger')=>document.getElementById('scannerAlert').innerHTML=`<div class="alert alert-${type} border-0 shadow-sm"><i class="bi bi-info-circle-fill me-2"></i>${message}</div>`;function onScanSuccess(decoded){if(!active)return;window.Livewire.dispatch('qrCodeLido',{codigo:decoded});stopScanner();alertBox('QRCode identificado. Confira o aluno e preencha as respostas.','success');}async function startScanner(){if(active)return;try{scanner=new Html5Qrcode('reader');await scanner.start({facingMode:'environment'},{fps:10,qrbox:{width:230,height:230}},onScanSuccess,()=>{});active=true;document.getElementById('startScanner').disabled=true;document.getElementById('stopScanner').disabled=false;alertBox('Câmera ativa. Aponte para o QRCode do aluno.','info');}catch(error){alertBox('Não foi possível acessar a câmera. Verifique as permissões do navegador.');}}async function stopScanner(){if(!scanner||!active)return;try{await scanner.stop();scanner.clear();}catch(error){}active=false;document.getElementById('startScanner').disabled=false;document.getElementById('stopScanner').disabled=true;}document.getElementById('startScanner').addEventListener('click',startScanner);document.getElementById('stopScanner').addEventListener('click',stopScanner);</script>@endpush
</x-app-layout>
